1	package agent
2	
3	import (
4		"context"
5		"fmt"
6		"path/filepath"
7		"slices"
8		"strings"
9		"sync"
10	
11		"github.com/entireio/cli/cmd/entire/cli/agent/types"
12	)
13	
14	var (
15		registryMu sync.RWMutex
16		registry   = make(map[types.AgentName]Factory)
17	)
18	
19	// Factory creates a new agent instance
20	type Factory func() Agent
21	
22	// Register adds an agent factory to the registry.
23	// Called from init() in each agent implementation.
24	func Register(name types.AgentName, factory Factory) {
25		registryMu.Lock()
26		defer registryMu.Unlock()
27		registry[name] = factory
28	}
29	
30	// Get retrieves an agent by name.
31	//
32	
33	func Get(name types.AgentName) (Agent, error) {
34		registryMu.RLock()
35		defer registryMu.RUnlock()
36	
37		factory, ok := registry[name]
38		if !ok {
39			return nil, fmt.Errorf("unknown agent: %s (available: %v)", name, List())
40		}
41		return factory(), nil
42	}
43	
44	// List returns all registered agent names in sorted order.
45	func List() []types.AgentName {
46		registryMu.RLock()
47		defer registryMu.RUnlock()
48	
49		names := make([]types.AgentName, 0, len(registry))
50		for name := range registry {
51			names = append(names, name)
52		}
53		slices.Sort(names)
54		return names
55	}
56	
57	// StringList returns user-facing agent names, excluding test-only agents.
58	func StringList() []string {
59		registryMu.RLock()
60		defer registryMu.RUnlock()
61	
62		names := make([]string, 0, len(registry))
63		for name, factory := range registry {
64			if to, ok := factory().(TestOnly); ok && to.IsTestOnly() {
65				continue
66			}
67			names = append(names, string(name))
68		}
69		slices.Sort(names)
70		return names
71	}
72	
73	// DetectAll returns all agents whose DetectPresence reports true.
74	// Agents are checked in sorted name order (via List()) for deterministic results.
75	// Returns an empty slice when no agent is detected.
76	func DetectAll(ctx context.Context) []Agent {
77		names := List() // sorted, lock-safe
78	
79		var detected []Agent
80		for _, name := range names {
81			ag, err := Get(name)
82			if err != nil {
83				continue
84			}
85			if present, err := ag.DetectPresence(ctx); err == nil && present {
86				detected = append(detected, ag)
87			}
88		}
89		return detected
90	}
91	
92	// Detect attempts to auto-detect which agent is being used.
93	// Iterates registered agents in sorted name order for deterministic results.
94	// Returns the first agent whose DetectPresence reports true.
95	func Detect(ctx context.Context) (Agent, error) {
96		detected := DetectAll(ctx)
97		if len(detected) == 0 {
98			return nil, fmt.Errorf("no agent detected (available: %v)", List())
99		}
100		return detected[0], nil
101	}
102	
103	// AgentForTranscriptPath returns the registered agent whose session directory
104	// for repoPath contains the given transcript path. Used to disambiguate which
105	// agent owns a session when multiple agents' hooks fire for the same session
106	// ID — a Cursor transcript path uniquely identifies a Cursor session even
107	// when Claude Code's hook is the one firing.
108	//
109	// Returns (nil, false) if transcriptPath is empty, no agent claims it, or any
110	// registry lookup fails. Match is by directory prefix (with a separator) so
111	// "/x/.claude/projects/abc.jsonl" doesn't accidentally match an agent rooted
112	// at "/x/.claude/projects/ab".
113	//
114	//nolint:revive // AgentForTranscriptPath: stutter is intentional for package callers (agent.AgentForTranscriptPath reads naturally)
115	func AgentForTranscriptPath(transcriptPath, repoPath string) (Agent, bool) {
116		if transcriptPath == "" {
117			return nil, false
118		}
119		abs, err := filepath.Abs(transcriptPath)
120		if err != nil {
121			abs = transcriptPath
122		}
123		for _, name := range List() {
124			ag, err := Get(name)
125			if err != nil {
126				continue
127			}
128			dir, err := ag.GetSessionDir(repoPath)
129			if err != nil || dir == "" {
130				continue
131			}
132			dirAbs, err := filepath.Abs(dir)
133			if err != nil {
134				dirAbs = dir
135			}
136			if pathHasDirPrefix(abs, dirAbs) {
137				return ag, true
138			}
139		}
140		return nil, false
141	}
142	
143	// pathHasDirPrefix reports whether path is contained within dir (or equals it).
144	// Adds a trailing separator before prefix-matching so /a/bc doesn't match /a/b.
145	func pathHasDirPrefix(path, dir string) bool {
146		if path == dir {
147			return true
148		}
149		if !strings.HasSuffix(dir, string(filepath.Separator)) {
150			dir += string(filepath.Separator)
151		}
152		return strings.HasPrefix(path, dir)
153	}
