155	// Agent name constants (registry keys)
156	const (
157		AgentNameClaudeCode     types.AgentName = "claude-code"
158		AgentNameCodex          types.AgentName = "codex"
159		AgentNameCopilotCLI     types.AgentName = "copilot-cli"
160		AgentNameCursor         types.AgentName = "cursor"
161		AgentNameFactoryAIDroid types.AgentName = "factoryai-droid"
162		AgentNameGemini         types.AgentName = "gemini"
163		AgentNameOpenCode       types.AgentName = "opencode"
164	)
165	
166	// Agent type constants (type identifiers stored in metadata/trailers)
167	const (
168		AgentTypeClaudeCode     types.AgentType = "Claude Code"
169		AgentTypeCodex          types.AgentType = "Codex"
170		AgentTypeCopilotCLI     types.AgentType = "Copilot CLI"
171		AgentTypeCursor         types.AgentType = "Cursor"
172		AgentTypeFactoryAIDroid types.AgentType = "Factory AI Droid"
173		AgentTypeGemini         types.AgentType = "Gemini CLI"
174		AgentTypeOpenCode       types.AgentType = "OpenCode"
175		AgentTypeUnknown        types.AgentType = "Unknown"
176	)
177	
178	// DefaultAgentName is the registry key for the default agent.
179	const DefaultAgentName types.AgentName = AgentNameClaudeCode
180	
181	// GetByAgentType retrieves an agent by its type identifier.
182	//
183	// Note: This uses a linear search that instantiates agents until a match is found.
184	// This is acceptable because:
185	//   - Agent count is small (~2-20 agents)
186	//   - Agent factories are lightweight (empty struct allocation)
187	//   - Called infrequently (commit hooks, rewind, debug commands - not hot paths)
188	//   - Cost is ~400ns worst case vs milliseconds for I/O operations
189	//
190	// Only optimize if agent count exceeds 100 or profiling shows this as a bottleneck.
191	func GetByAgentType(agentType types.AgentType) (Agent, error) {
192		registryMu.RLock()
193		defer registryMu.RUnlock()
194	
195		for _, factory := range registry {
196			ag := factory()
197			if ag.Type() == agentType {
198				return ag, nil
199			}
200		}
201	
202		return nil, fmt.Errorf("unknown agent type: %s", agentType)
203	}
204	
205	// AllProtectedDirs returns the union of ProtectedDirs from all registered agents.
206	func AllProtectedDirs() []string {
207		// Copy factories under the lock, then release before calling external code.
208		registryMu.RLock()
209		factories := make([]Factory, 0, len(registry))
210		for _, f := range registry {
211			factories = append(factories, f)
212		}
213		registryMu.RUnlock()
214	
215		seen := make(map[string]struct{})
216		var dirs []string
217		for _, factory := range factories {
218			for _, d := range factory().ProtectedDirs() {
219				if _, ok := seen[d]; !ok {
220					seen[d] = struct{}{}
221					dirs = append(dirs, d)
222				}
223			}
224		}
225		slices.Sort(dirs)
226		return dirs
227	}
228	
229	// AllProtectedFiles returns the union of ProtectedFiles from all registered agents.
230	func AllProtectedFiles() []string {
231		// Copy factories under the lock, then release before calling external code.
232		registryMu.RLock()
233		factories := make([]Factory, 0, len(registry))
234		for _, f := range registry {
235			factories = append(factories, f)
236		}
237		registryMu.RUnlock()
238	
239		seen := make(map[string]struct{})
240		var files []string
241		for _, factory := range factories {
242			pf, ok := factory().(ProtectedFilesProvider)
243			if !ok {
244				continue
245			}
246			for _, file := range pf.ProtectedFiles() {
247				if _, ok := seen[file]; !ok {
248					seen[file] = struct{}{}
249					files = append(files, file)
250				}
251			}
252		}
253		slices.Sort(files)
254		return files
255	}
256	
257	// Default returns the default agent.
258	// Returns nil if the default agent is not registered.
259	//
260	//nolint:errcheck // Factory pattern returns interface; error is acceptable to ignore for default
261	func Default() Agent {
262		a, _ := Get(DefaultAgentName)
263		return a
264	}
