3	package filelock
4	
5	import (
6		"fmt"
7		"os"
8	
9		"golang.org/x/sys/windows"
10	)
11	
12	type windowsLock struct {
13		f *os.File
14	}
15	
16	func (w *windowsLock) release() error {
17		overlapped := &windows.Overlapped{}
18		_ = windows.UnlockFileEx(windows.Handle(w.f.Fd()), 0, ^uint32(0), ^uint32(0), overlapped) //nolint:errcheck // Close below also releases
19		if err := w.f.Close(); err != nil {
20			return fmt.Errorf("close lock file: %w", err)
21		}
22		return nil
23	}
24	
25	//nolint:ireturn // intentional: cross-platform interface used only by filelock.Acquire
26	func acquireImpl(path string) (lockImpl, error) {
27		f, err := os.OpenFile(path, os.O_CREATE|os.O_RDWR, 0o600) //nolint:gosec // path is built from caller-validated session ID
28		if err != nil {
29			return nil, fmt.Errorf("open lock file %q: %w", path, err)
30		}
31		overlapped := &windows.Overlapped{}
32		if err := windows.LockFileEx(windows.Handle(f.Fd()), windows.LOCKFILE_EXCLUSIVE_LOCK, 0, ^uint32(0), ^uint32(0), overlapped); err != nil {
33			_ = f.Close() //nolint:errcheck // best-effort cleanup on lock failure
34			return nil, fmt.Errorf("LockFileEx %q: %w", path, err)
35		}
36		return &windowsLock{f: f}, nil
37	}
