1	package strategy
2	
3	import (
4		"context"
5		"errors"
6		"fmt"
7		"log/slog"
8		"os"
9		"path/filepath"
10		"strings"
11	
12		"github.com/entireio/cli/cmd/entire/cli/agent"
13		"github.com/entireio/cli/cmd/entire/cli/agent/types"
14		"github.com/entireio/cli/cmd/entire/cli/filelock"
15		"github.com/entireio/cli/cmd/entire/cli/jsonutil"
16		"github.com/entireio/cli/cmd/entire/cli/logging"
17		"github.com/entireio/cli/cmd/entire/cli/paths"
18		"github.com/entireio/cli/cmd/entire/cli/session"
19		"github.com/entireio/cli/cmd/entire/cli/validation"
20	)
21	
22	// Session state management functions shared across all strategies.
23	// SessionState is stored in .git/entire-sessions/{session_id}.json
24	
25	// getSessionStateDir returns the path to the session state directory.
26	// This is stored in the git common dir so it's shared across all worktrees.
27	func getSessionStateDir(ctx context.Context) (string, error) {
28		commonDir, err := GetGitCommonDir(ctx)
29		if err != nil {
30			return "", err
31		}
32		return filepath.Join(commonDir, session.SessionStateDirName), nil
33	}
34	
35	// sessionStateFile returns the path to a session state file.
36	func sessionStateFile(ctx context.Context, sessionID string) (string, error) {
37		stateDir, err := getSessionStateDir(ctx)
38		if err != nil {
39			return "", err
40		}
41		return filepath.Join(stateDir, sessionID+".json"), nil
42	}
43	
44	// LoadSessionState loads the session state for the given session ID.
45	// Returns (nil, nil) when session file doesn't exist or session is stale (not an error condition).
46	// Stale sessions are automatically deleted by the underlying StateStore.
47	func LoadSessionState(ctx context.Context, sessionID string) (*SessionState, error) {
48		store, err := session.NewStateStore(ctx)
49		if err != nil {
50			return nil, fmt.Errorf("failed to create state store: %w", err)
51		}
52	
53		state, err := store.Load(ctx, sessionID)
54		if err != nil {
55			return nil, fmt.Errorf("failed to load session state: %w", err)
56		}
57		return state, nil
58	}
59	
60	// SaveSessionState saves the session state atomically.
61	func SaveSessionState(ctx context.Context, state *SessionState) error {
62		// Validate session ID to prevent path traversal
63		if err := validation.ValidateSessionID(state.SessionID); err != nil {
64			return fmt.Errorf("invalid session ID: %w", err)
65		}
66	
67		stateDir, err := getSessionStateDir(ctx)
68		if err != nil {
69			return fmt.Errorf("failed to get session state directory: %w", err)
70		}
71	
72		if err := os.MkdirAll(stateDir, 0o750); err != nil {
73			return fmt.Errorf("failed to create session state directory: %w", err)
74		}
75	
76		data, err := jsonutil.MarshalIndentWithNewline(state, "", "  ")
77		if err != nil {
78			return fmt.Errorf("failed to marshal session state: %w", err)
79		}
80	
81		stateFile, err := sessionStateFile(ctx, state.SessionID)
82		if err != nil {
83			return fmt.Errorf("failed to get session state file path: %w", err)
84		}
85	
86		// Atomic write: write to temp file, then rename
87		tmpFile := stateFile + ".tmp"
88		if err := os.WriteFile(tmpFile, data, 0o600); err != nil {
89			return fmt.Errorf("failed to write session state: %w", err)
90		}
91		if err := os.Rename(tmpFile, stateFile); err != nil {
92			return fmt.Errorf("failed to rename session state file: %w", err)
93		}
94		return nil
95	}
96	
97	// ListSessionStates returns all session states from the state directory.
98	// This is a package-level function that doesn't require a specific strategy instance.
99	func ListSessionStates(ctx context.Context) ([]*SessionState, error) {
100		store, err := session.NewStateStore(ctx)
101		if err != nil {
102			return nil, fmt.Errorf("failed to create state store: %w", err)
103		}
104	
105		states, err := store.List(ctx)
106		if err != nil {
107			return nil, fmt.Errorf("failed to list session states: %w", err)
108		}
109		return states, nil
110	}
111	
112	// FindMostRecentSession returns the session ID of the most recently interacted session
113	// (by LastInteractionTime) in the current worktree. Returns empty string if no sessions exist.
114	// Scoping to the current worktree prevents cross-worktree pollution in log routing.
115	// Falls back to unfiltered search if the worktree path can't be determined.
116	func FindMostRecentSession(ctx context.Context) string {
117		states, err := ListSessionStates(ctx)
118		if err != nil || len(states) == 0 {
119			return ""
120		}
121	
122		// Scope to current worktree to prevent cross-worktree pollution.
123		worktreePath, wpErr := paths.WorktreeRoot(ctx)
124		if wpErr == nil && worktreePath != "" {
125			var filtered []*SessionState
126			for _, s := range states {
127				if s.WorktreePath == worktreePath {
128					filtered = append(filtered, s)
129				}
130			}
131			if len(filtered) > 0 {
132				states = filtered
133			}
134			// If no sessions match the worktree, fall back to all sessions
135		}
136	
137		var best *SessionState
138		for _, s := range states {
139			if s.LastInteractionTime == nil {
140				continue
141			}
142			if best == nil || s.LastInteractionTime.After(*best.LastInteractionTime) {
143				best = s
144			}
145		}
146		if best != nil {
147			return best.SessionID
148		}
149	
150		// Fallback: return most recently started session
151		for _, s := range states {
152			if best == nil || s.StartedAt.After(best.StartedAt) {
153				best = s
154			}
155		}
156		if best != nil {
157			return best.SessionID
158		}
159		return ""
160	}
161	
162	// TransitionAndLog runs a session phase transition, applies actions via the
163	// handler, and logs the transition. Returns the first handler error from
164	// ApplyTransition (if any) so callers can surface it. The error is also
165	// logged internally for diagnostics.
166	// This is the single entry point for all state machine transitions to ensure
167	// consistent logging of phase changes.
168	func TransitionAndLog(goCtx context.Context, state *SessionState, event session.Event, ctx session.TransitionContext, handler session.ActionHandler) error {
169		oldPhase := state.Phase
170		result := session.Transition(oldPhase, event, ctx)
171		logCtx := logging.WithComponent(goCtx, "session")
172	
173		handlerErr := session.ApplyTransition(goCtx, state, result, handler)
174		if handlerErr != nil {
175			logging.Error(logCtx, "action handler error during transition",
176				slog.String("session_id", state.SessionID),
177				slog.String("event", event.String()),
178				slog.Any("error", handlerErr),
179			)
180		}
181	
182		if result.NewPhase != oldPhase {
183			logging.Info(logCtx, "phase transition",
184				slog.String("session_id", state.SessionID),
185				slog.String("event", event.String()),
186				slog.String("from", string(oldPhase)),
187				slog.String("to", string(result.NewPhase)),
188			)
189		} else {
190			logging.Debug(logCtx, "phase unchanged",
191				slog.String("session_id", state.SessionID),
192				slog.String("event", event.String()),
193				slog.String("phase", string(result.NewPhase)),
194				slog.Any("result", result),
195			)
196		}
197	
198		if handlerErr != nil {
199			return fmt.Errorf("transition %s: %w", event, handlerErr)
200		}
201		return nil
202	}
203	
204	// StoreModelHint writes the LLM model name to a lightweight hint file
205	// (.git/entire-sessions/{session_id}.model) for cross-process persistence.
206	//
207	// Why a separate file instead of SessionState?
208	//
209	// SessionState requires BaseCommit (used for shadow branch naming, checkpoint
210	// writing, doctor classification, etc.) and is only created during TurnStart
211	// when the git repo is fully inspected. Some agents report the model on earlier
212	// hooks that fire as separate CLI processes before TurnStart:
213	//
214	//   - Claude Code sends "model" on SessionStart (before any TurnStart)
215	//   - Gemini CLI sends "llm_request.model" on BeforeModel (after TurnStart,
216	//     so handleLifecycleModelUpdate writes to SessionState directly when it
217	//     exists and only falls back to this hint file otherwise)
218	//
219	// The hint is read by handleLifecycleTurnStart/TurnEnd when event.Model is
220	// empty, passed to InitializeSession, and persisted in state.ModelName. After
221	// that the hint file is redundant — it sits unused until ClearSessionState
222	// removes it alongside the session state file.
223	func StoreModelHint(ctx context.Context, sessionID, model string) error {
224		if err := validation.ValidateSessionID(sessionID); err != nil {
225			return fmt.Errorf("invalid session ID: %w", err)
226		}
227		if model == "" {
228			return nil
229		}
230	
231		stateDir, err := getSessionStateDir(ctx)
232		if err != nil {
233			return fmt.Errorf("failed to get session state directory: %w", err)
234		}
235		if err := os.MkdirAll(stateDir, 0o750); err != nil {
236			return fmt.Errorf("failed to create session state directory: %w", err)
237		}
238	
239		hintFile := filepath.Join(stateDir, sessionID+".model")
240		if err := os.WriteFile(hintFile, []byte(model), 0o600); err != nil {
241			return fmt.Errorf("failed to write model hint file: %w", err)
242		}
243		return nil
244	}
245	
246	// LoadModelHint reads the LLM model name from the hint file for the given session.
247	// Returns empty string if the hint file doesn't exist or can't be read.
248	func LoadModelHint(ctx context.Context, sessionID string) string {
249		if err := validation.ValidateSessionID(sessionID); err != nil {
250			return ""
251		}
252	
253		stateDir, err := getSessionStateDir(ctx)
254		if err != nil {
255			logging.Warn(logging.WithComponent(ctx, "session"), "failed to resolve state dir for model hint",
256				slog.String("session_id", sessionID),
257				slog.Any("error", err))
258			return ""
259		}
260	
261		hintPath := filepath.Join(stateDir, sessionID+".model")
262		data, err := os.ReadFile(hintPath) //nolint:gosec // sessionID is validated above
263		if err != nil {
264			if !os.IsNotExist(err) {
265				logging.Warn(logging.WithComponent(ctx, "session"), "failed to read model hint file",
266					slog.String("path", hintPath),
267					slog.Any("error", err))
268			}
269			return ""
270		}
271		return strings.TrimSpace(string(data))
272	}
273	
274	// AcquireSessionLock takes an exclusive per-session-id lock. Used to
275	// serialize concurrent processes that initialize the same session — when
276	// Cursor IDE forwards a single user prompt to both its own hook system and
277	// Claude Code's, two `entire` hook processes can otherwise each
278	// create-from-scratch in parallel and race for the last write. With the lock
279	// the second arrival sees the existing state and goes through the cheap
280	// update path (correctSessionAgentType repairs AgentType if the transcript
281	// path indicates a different agent).
282	//
283	// Lock files live under a dedicated `entire-locks/` directory in the git
284	// common dir — separate from `entire-sessions/` so callers that enumerate
285	// session state files (status, doctor, tests) don't have to filter lock
286	// artifacts.
287	func AcquireSessionLock(ctx context.Context, sessionID string) (*filelock.Lock, error) {
288		if err := validation.ValidateSessionID(sessionID); err != nil {
289			return nil, fmt.Errorf("invalid session ID: %w", err)
290		}
291		commonDir, err := GetGitCommonDir(ctx)
292		if err != nil {
293			return nil, fmt.Errorf("failed to get git common dir: %w", err)
294		}
295		lockDir := filepath.Join(commonDir, "entire-locks")
296		if err := os.MkdirAll(lockDir, 0o750); err != nil {
297			return nil, fmt.Errorf("failed to create lock directory: %w", err)
298		}
299		lock, err := filelock.Acquire(filepath.Join(lockDir, sessionID+".lock"))
300		if err != nil {
301			return nil, fmt.Errorf("failed to acquire session lock: %w", err)
302		}
303		return lock, nil
304	}
305	
306	// StoreAgentTypeHint records the agent type that owns a session before
307	// SessionState exists. Used by the lifecycle dispatcher when SessionStart fires
308	// (state isn't created until TurnStart, so we need a place to remember which
309	// agent claimed the session first).
310	//
311	// Semantics: first writer wins. When multiple agents fire hooks for the same
312	// session ID — e.g., Cursor IDE running cursor-agent while also forwarding to
313	// Claude Code's hook system — only the agent that fires SessionStart first
314	// gets recorded. Subsequent calls return nil without overwriting.
315	//
316	// At TurnStart, InitializeSession reads this hint to override agentType when
317	// the hook firing isn't the same agent that owns the session. After the state
318	// file is written, the hint is unused but remains until ClearSessionState
319	// removes it alongside the state file.
320	//
321	// Returns (created=true) when this call wrote the hint, (created=false) when
322	// the hint already existed (no-op) or agentType was empty/Unknown.
323	//
324	// Callers can use the created bool to gate one-time-per-session side effects
325	// — e.g., the SessionStart banner: if Gemini fires SessionStart twice (once
326	// for source=startup, once for source=resume) we don't want to print the
327	// banner twice. The first call creates the hint and returns created=true;
328	// the second sees the hint and returns created=false.
329	func StoreAgentTypeHint(ctx context.Context, sessionID string, agentType types.AgentType) (created bool, err error) {
330		if vErr := validation.ValidateSessionID(sessionID); vErr != nil {
331			return false, fmt.Errorf("invalid session ID: %w", vErr)
332		}
333		if agentType == "" || agentType == agent.AgentTypeUnknown {
334			return false, nil
335		}
336	
337		stateDir, sErr := getSessionStateDir(ctx)
338		if sErr != nil {
339			return false, fmt.Errorf("failed to get session state directory: %w", sErr)
340		}
341		if mErr := os.MkdirAll(stateDir, 0o750); mErr != nil {
342			return false, fmt.Errorf("failed to create session state directory: %w", mErr)
343		}
344	
345		hintFile := filepath.Join(stateDir, sessionID+".agent")
346		f, oErr := os.OpenFile(hintFile, os.O_CREATE|os.O_EXCL|os.O_WRONLY, 0o600) //nolint:gosec // hintFile path is built from validated sessionID
347		if oErr != nil {
348			if errors.Is(oErr, os.ErrExist) {
349				// First-writer-wins: another caller already claimed this session.
350				return false, nil
351			}
352			return false, fmt.Errorf("failed to create agent hint file: %w", oErr)
353		}
354		defer f.Close()
355		if _, wErr := f.WriteString(string(agentType)); wErr != nil {
356			return false, fmt.Errorf("failed to write agent hint file: %w", wErr)
357		}
358		return true, nil
359	}
360	
361	// LoadAgentTypeHint reads the agent type hint written by SessionStart.
362	// Returns empty string if the hint file doesn't exist, can't be read, or the
363	// value isn't a registered agent type.
364	func LoadAgentTypeHint(ctx context.Context, sessionID string) types.AgentType {
365		if err := validation.ValidateSessionID(sessionID); err != nil {
366			return ""
367		}
368	
369		stateDir, err := getSessionStateDir(ctx)
370		if err != nil {
371			logging.Warn(logging.WithComponent(ctx, "session"), "failed to resolve state dir for agent hint",
372				slog.String("session_id", sessionID),
373				slog.Any("error", err))
374			return ""
375		}
376	
377		hintPath := filepath.Join(stateDir, sessionID+".agent")
378		data, err := os.ReadFile(hintPath) //nolint:gosec // sessionID is validated above
379		if err != nil {
380			if !os.IsNotExist(err) {
381				logging.Warn(logging.WithComponent(ctx, "session"), "failed to read agent hint file",
382					slog.String("path", hintPath),
383					slog.Any("error", err))
384			}
385			return ""
386		}
387		return types.AgentType(strings.TrimSpace(string(data)))
388	}
389	
390	// ClearSessionState removes the session state file for the given session ID.
391	func ClearSessionState(ctx context.Context, sessionID string) error {
392		// Validate session ID to prevent path traversal
393		if err := validation.ValidateSessionID(sessionID); err != nil {
394			return fmt.Errorf("invalid session ID: %w", err)
395		}
396	
397		stateDir, err := getSessionStateDir(ctx)
398		if err != nil {
399			return fmt.Errorf("failed to get session state directory: %w", err)
400		}
401	
402		// Remove all files for this session (state .json, .model hint, any future hint files).
403		matches, _ := filepath.Glob(filepath.Join(stateDir, sessionID+".*")) //nolint:errcheck // pattern is always valid
404		for _, f := range matches {
405			_ = os.Remove(f)
406		}
407	
408		// Remove the lock file (lives in a separate directory; see AcquireSessionLock).
409		if commonDir, cdErr := GetGitCommonDir(ctx); cdErr == nil {
410			_ = os.Remove(filepath.Join(commonDir, "entire-locks", sessionID+".lock"))
411		}
412	
413		return nil
414	}
