11	func TestAcquire_SerializesGoroutines(t *testing.T) {
12		t.Parallel()
13	
14		path := filepath.Join(t.TempDir(), "test.lock")
15	
16		const goroutines = 8
17		var (
18			holders  atomic.Int32
19			maxConc  atomic.Int32
20			finished atomic.Int32
21		)
22	
23		var wg sync.WaitGroup
24		for range goroutines {
25			wg.Add(1)
26			go func() {
27				defer wg.Done()
28				lock, err := Acquire(path)
29				if err != nil {
30					t.Errorf("Acquire() error = %v", err)
31					return
32				}
33				defer func() {
34					if rErr := lock.Release(); rErr != nil {
35						t.Errorf("Release() error = %v", rErr)
36					}
37					finished.Add(1)
38				}()
39	
40				// Track concurrent holders. Must always be 1 under exclusive lock.
41				cur := holders.Add(1)
42				if cur > maxConc.Load() {
43					maxConc.Store(cur)
44				}
45	
46				// Hold the lock briefly to give other goroutines a real chance to
47				// race for it. Without this, Goroutine 1 might release before any
48				// peer attempts Acquire, masking a broken lock.
49				time.Sleep(5 * time.Millisecond)
50	
51				holders.Add(-1)
52			}()
53		}
54		wg.Wait()
55	
56		if finished.Load() != goroutines {
57			t.Fatalf("expected %d goroutines to finish, got %d", goroutines, finished.Load())
58		}
59		if got := maxConc.Load(); got != 1 {
60			t.Errorf("max concurrent holders = %d, want 1 (lock is not exclusive)", got)
61		}
62	}
63	
64	func TestRelease_Idempotent(t *testing.T) {
65		t.Parallel()
66	
67		path := filepath.Join(t.TempDir(), "test.lock")
68		lock, err := Acquire(path)
69		if err != nil {
70			t.Fatalf("Acquire() error = %v", err)
71		}
72		if err := lock.Release(); err != nil {
73			t.Fatalf("first Release() error = %v", err)
74		}
75		if err := lock.Release(); err != nil {
76			t.Errorf("second Release() should be a no-op, got: %v", err)
77		}
78	}
79	
80	func TestRelease_NilLock_NoOp(t *testing.T) {
81		t.Parallel()
82	
83		var lock *Lock
84		if err := lock.Release(); err != nil {
85			t.Errorf("Release() on nil lock should be a no-op, got: %v", err)
86		}
87	}
