522	func TestHandleLifecycleCompaction_PreservesTranscriptOffset(t *testing.T) {
523		// Cannot use t.Parallel() because we use t.Chdir()
524		tmpDir := t.TempDir()
525		t.Chdir(tmpDir)
526	
527		// Initialize git repo with a commit (not empty)
528		setupGitRepoWithCommit(t, tmpDir)
529		paths.ClearWorktreeRootCache()
530	
531		// Create .entire directory structure
532		if err := os.MkdirAll(paths.EntireDir, 0o755); err != nil {
533			t.Fatalf("Failed to create .entire: %v", err)
534		}
535	
536		// Create a transcript file
537		transcriptPath := filepath.Join(tmpDir, "transcript.jsonl")
538		transcriptContent := `{"type":"user","message":{"role":"user","content":"test prompt"}}` + "\n"
539		if err := os.WriteFile(transcriptPath, []byte(transcriptContent), 0o644); err != nil {
540			t.Fatalf("Failed to create transcript: %v", err)
541		}
542	
543		sessionID := "compaction-test-session"
544	
545		// Create session state with non-zero transcript offset (set by prior condensation)
546		sessionState := &strategy.SessionState{
547			SessionID:                 sessionID,
548			StartedAt:                 time.Now(),
549			CheckpointTranscriptStart: 50,
550		}
551		if err := strategy.SaveSessionState(context.Background(), sessionState); err != nil {
552			t.Fatalf("Failed to save session state: %v", err)
553		}
554	
555		ag := newMockAgent()
556		event := &agent.Event{
557			Type:       agent.Compaction,
558			SessionID:  sessionID,
559			SessionRef: transcriptPath,
560		}
561	
562		// Compaction should NOT reset the transcript offset.
563		// Many agents (e.g., Gemini) fire pre-compress as a no-op after every tool call;
564		// resetting the offset causes stale files to re-appear in carry-forward.
565		err := handleLifecycleCompaction(context.Background(), ag, event)
566		if err != nil {
567			t.Logf("handleLifecycleCompaction returned error (expected in minimal test): %v", err)
568		}
569	
570		// Verify CheckpointTranscriptStart was preserved (not reset to 0)
571		loadedState, loadErr := strategy.LoadSessionState(context.Background(), sessionID)
572		if loadErr != nil {
573			t.Fatalf("Failed to load session state after compaction: %v", loadErr)
574		}
575		require.NotNil(t, loadedState, "Session state is nil after compaction")
576		if loadedState.CheckpointTranscriptStart != 50 {
577			t.Errorf("CheckpointTranscriptStart = %d, want 50 (compaction should preserve offset)",
578				loadedState.CheckpointTranscriptStart)
579		}
580	}
