641	func TestDispatchLifecycleEvent_RoutesToCorrectHandler(t *testing.T) {
642		// NOT parallel: uses t.Chdir to isolate from real repo state.
643		// Without this, the SubagentEnd case creates .git/entire-sessions/test.json
644		// in the real repo whenever untracked files exist, because DetectFileChanges
645		// reports them as new files and SaveTaskStep falls back to initializeSession.
646		tmpDir := t.TempDir()
647		testutil.InitRepo(t, tmpDir)
648		testutil.WriteFile(t, tmpDir, "init.txt", "init")
649		testutil.GitAdd(t, tmpDir, "init.txt")
650		testutil.GitCommit(t, tmpDir, "init")
651		t.Chdir(tmpDir)
652	
653		// Test that each event type is routed (we can't easily verify which handler
654		// was called without dependency injection, but we can verify no panic and
655		// expected error types for each event type with minimal required data)
656	
657		testCases := []struct {
658			name        string
659			eventType   agent.EventType
660			sessionID   string
661			expectError bool
662			errorSubstr string
663		}{
664			{
665				name:        "SessionStart with empty session ID",
666				eventType:   agent.SessionStart,
667				sessionID:   "",
668				expectError: true,
669				errorSubstr: "no session_id",
670			},
671			{
672				name:        "TurnStart with empty session ID",
673				eventType:   agent.TurnStart,
674				sessionID:   "",
675				expectError: true,
676				errorSubstr: "no session_id",
677			},
678			{
679				name:        "TurnEnd with empty transcript",
680				eventType:   agent.TurnEnd,
681				sessionID:   "test",
682				expectError: true,
683				errorSubstr: "transcript file not specified",
684			},
685			{
686				name:        "Compaction with empty transcript is no-op",
687				eventType:   agent.Compaction,
688				sessionID:   "test",
689				expectError: false, // Compaction just resets offset; doesn't read transcript
690			},
691			{
692				name:        "SessionEnd with empty session ID is no-op",
693				eventType:   agent.SessionEnd,
694				sessionID:   "",
695				expectError: false,
696			},
697			{
698				name:        "SubagentStart with valid data",
699				eventType:   agent.SubagentStart,
700				sessionID:   "test",
701				expectError: true, // Will fail due to CapturePreTaskState needing git repo
702				errorSubstr: "failed to capture pre-task state",
703			},
704			{
705				name:        "SubagentEnd with valid data",
706				eventType:   agent.SubagentEnd,
707				sessionID:   "test",
708				expectError: false, // Succeeds when run from a valid git repo
709			},
710			{
711				name:        "ModelUpdate with empty model is no-op",
712				eventType:   agent.ModelUpdate,
713				sessionID:   "test",
714				expectError: false,
715			},
716			{
717				name:        "ModelUpdate with empty session ID is no-op",
718				eventType:   agent.ModelUpdate,
719				sessionID:   "",
720				expectError: false,
721			},
722		}
723	
724		for _, tc := range testCases {
725			t.Run(tc.name, func(t *testing.T) {
726				ag := newMockAgent()
727				event := &agent.Event{
728					Type:      tc.eventType,
729					SessionID: tc.sessionID,
730					Timestamp: time.Now(),
731				}
732	
733				err := DispatchLifecycleEvent(context.Background(), ag, event)
734	
735				if tc.expectError {
736					if err == nil {
737						t.Errorf("expected error containing %q, got nil", tc.errorSubstr)
738					} else if !strings.Contains(err.Error(), tc.errorSubstr) {
739						t.Errorf("expected error containing %q, got: %v", tc.errorSubstr, err)
740					}
741				} else {
742					if err != nil {
743						t.Errorf("expected no error, got: %v", err)
744					}
745				}
746			})
747		}
