752	// setupGitRepoWithCommit initializes a git repo with an initial commit.
753	func setupGitRepoWithCommit(t *testing.T, dir string) {
754		t.Helper()
755	
756		// Initialize git repo
757		if err := os.MkdirAll(filepath.Join(dir, ".git", "objects"), 0o755); err != nil {
758			t.Fatalf("Failed to create .git/objects: %v", err)
759		}
760		if err := os.MkdirAll(filepath.Join(dir, ".git", "refs", "heads"), 0o755); err != nil {
761			t.Fatalf("Failed to create .git/refs/heads: %v", err)
762		}
763		if err := os.WriteFile(filepath.Join(dir, ".git", "HEAD"), []byte("ref: refs/heads/main\n"), 0o644); err != nil {
764			t.Fatalf("Failed to create HEAD: %v", err)
765		}
766	
767		// Create a dummy file to commit
768		if err := os.WriteFile(filepath.Join(dir, "README.md"), []byte("# Test\n"), 0o644); err != nil {
769			t.Fatalf("Failed to create README.md: %v", err)
770		}
