284	// TestFindMostRecentSession_FiltersByWorktree tests that FindMostRecentSession
285	// returns sessions from the current worktree, not from other worktrees.
286	func TestFindMostRecentSession_FiltersByWorktree(t *testing.T) {
287		dir := t.TempDir()
288		_, err := git.PlainInit(dir, false)
289		if err != nil {
290			t.Fatalf("failed to init git repo: %v", err)
291		}
292	
293		t.Chdir(dir)
294	
295		// Get the resolved worktree path (git resolves symlinks, e.g. /var → /private/var on macOS)
296		resolvedDir, err := paths.WorktreeRoot(context.Background())
297		if err != nil {
298			t.Fatalf("paths.WorktreeRoot() error = %v", err)
299		}
300	
301		older := time.Now().Add(-1 * time.Hour)
302		newer := time.Now()
303	
304		// Session from a different worktree (more recent)
305		otherWorktree := &SessionState{
306			SessionID:           "other-worktree-session",
307			BaseCommit:          "abc1234",
308			WorktreePath:        "/some/other/worktree",
309			StartedAt:           newer,
310			LastInteractionTime: &newer,
311			Phase:               "idle",
312		}
313	
314		// Session from current worktree (older)
315		currentWorktree := &SessionState{
316			SessionID:           "current-worktree-session",
317			BaseCommit:          "xyz7890",
318			WorktreePath:        resolvedDir, // matches current worktree
319			StartedAt:           older,
320			LastInteractionTime: &older,
321			Phase:               "idle",
322		}
323	
324		if err := SaveSessionState(context.Background(), otherWorktree); err != nil {
325			t.Fatalf("SaveSessionState() error = %v", err)
326		}
327		if err := SaveSessionState(context.Background(), currentWorktree); err != nil {
328			t.Fatalf("SaveSessionState() error = %v", err)
329		}
330	
331		// FindMostRecentSession should return the current worktree's session,
332		// not the other worktree's session (even though it's more recent).
333		result := FindMostRecentSession(context.Background())
334		if result != "current-worktree-session" {
335			t.Errorf("FindMostRecentSession(context.Background()) = %q, want %q (should prefer current worktree)",
336				result, "current-worktree-session")
337		}
338	}
