477	// captureStdout swaps os.Stdout for a pipe, runs fn, and returns what was
478	// written. Sequential (no t.Parallel) because os.Stdout is process-global.
479	func captureStdout(t *testing.T, fn func()) string {
480		t.Helper()
481		r, w, err := os.Pipe()
482		require.NoError(t, err)
483	
484		original := os.Stdout
485		os.Stdout = w
486	
487		done := make(chan []byte, 1)
488		go func() {
489			data, _ := io.ReadAll(r) //nolint:errcheck // best-effort drain
490			done <- data
491		}()
492	
493		fn()
494		require.NoError(t, w.Close())
495		os.Stdout = original
496		got := <-done
497		require.NoError(t, r.Close())
498		return string(got)
499	}
