			slog.String("session_id", sessionID),
			slog.String("error", lockErr.Error()))
	} else {
		defer func() {
			if rErr := lock.Release(); rErr != nil {
				logging.Warn(logging.WithComponent(ctx, "hooks"), "failed to release session lock",
					slog.String("session_id", sessionID),
					slog.String("error", rErr.Error()))
